// apply_jt_kernel — 워프별 segmented reduction
typedef cub::WarpReduce<scalar_t> WarpReduce;
__shared__ typename WarpReduce::TempStorage temp_storage[NUM_WARPS];

// 동일한 Gaussian ID를 가진 스레드들끼리만 reduce
const int32_t prev_global_id = __shfl_up_sync(mask, global_id, 1);
const bool head_flag = (lane_id == 0) || (global_id != prev_global_id);

scalar_t grad_sum = WarpReduce(temp_storage[warp_id])
.HeadSegmentedSum(grad, head_flag);
__syncwarp(mask);

if (head_flag) {
atomicAdd(&g_vec[pos_out], grad_sum); // 세그먼트당 1회만 atomic
}
```

